import bisect as bs
for _ in range(int(input())):
	n = int(input())
	a = list(map(int, input().split()))
	if n <= 2:
		print(n)
		continue
	(stack, m, p) = ([a[0]], [], [(1000000, 0)])
	for v in a[1:]:
		k = bs.bisect_right(m, v)
		if k == len(m):
			stack.append(v)
			m.append(min(stack[-1], stack[-2]))
		else:
			stack[k + 1] = m[k] = v
		while p[-1][0] <= v:
			(vv, kk) = p.pop()
			m[kk] = min(m[kk], vv)
			stack[kk + 1] = min(stack[kk + 1], v)
		if k + 1 < len(m):
			p.append((v, k + 1))
	print(len(stack))
